    static readonly Dictionary<(string, int), Texture2D> Cache = new();

    /// <summary>The icon rasterized at px pixels (white strokes; buttons tint it with their font colour).</summary>
    public static Texture2D Get(string name, int px = 40)
    {
        if (Cache.TryGetValue((name, px), out var t)) return t;
        var img = new Image();
        var err = img.LoadSvgFromString(Svg[name], px / 24f);
        t = err == Error.Ok ? ImageTexture.CreateFromImage(img) : null;
        Cache[(name, px)] = t;
        return t;
    }
